// ── 会话摘要与轮换 ────────────────────────────────────────────────────
// 每轮记一次 turn；达到 rotateTurns 且安静下来后，先摘要、再退役旧会话。
function noteSessionTurn(key) {
  state.sessionTurns = state.sessionTurns || {};
  state.sessionTurns[key] = (Number(state.sessionTurns[key]) || 0) + 1;
  state.sessionStartedAt = state.sessionStartedAt || {};
  if (!state.sessionStartedAt[key]) state.sessionStartedAt[key] = Date.now();
  saveState();
}

function sessionWindowStart(key) {
  state.sessionStartedAt = state.sessionStartedAt || {};
  if (!state.sessionStartedAt[key]) {
    state.sessionStartedAt[key] = Date.now();
    saveState();
  }
  return state.sessionStartedAt[key];
}

const rotationTimers = new Map();
// 摘要失败后的退避：避免每轮/每 45 秒重试一次，把 token 烧在同一个失败上。
const summaryFailures = new Map();
function scheduleRotationCheck(key) {
  if (cfg.socialV2?.context?.autoRotate === false) return;
  if (rotationTimers.has(key)) return;
  const delay = Math.max(15000, Number(cfg.socialV2?.context?.rotateCheckMs) || 45000);
  const timer = setTimeout(() => {
    rotationTimers.delete(key);
    void maybeRotateSession(key).catch((error) => log(`context rotate failed: ${error?.message || error}`));
  }, delay);
  timer.unref?.();
  rotationTimers.set(key, timer);
}

async function summarizeSession(key, { force = false } = {}) {
  const minMessages = Math.max(4, Number(cfg.socialV2?.context?.summaryMinMessages) || 8);
  const tailKeep = Math.max(0, Number(cfg.socialV2?.context?.rotateKeepMessages) || 12);
  // 手动摘要（force）重收整段，不受上一条摘要的 period_end 限制；自动摘要只收新消息。
  const latest = force ? 0 : await memoryRequest('/summaries', { key, limit: 1 }, 4000)
    .then((r) => Number(r.summaries?.[0]?.period_end) || 0).catch(() => 0);
  const data = await memoryRequest('/messages', { key, afterAt: latest, beforeAt: Date.now(), limit: 400, oldestFirst: true }, 6000);
  const messages = Array.isArray(data.messages) ? data.messages : [];
  // 轮换时留最后 N 条做原文尾巴；手动摘要则整段都收。
  const body = force ? messages : messages.slice(0, Math.max(0, messages.length - tailKeep));
  if (body.length < (force ? 1 : minMessages)) return { ok: false, reason: 'too-few' };

  const periodStart = Number(body[0]?.at) || latest;
  const periodEnd = Number(body[body.length - 1]?.at) || Date.now();
  const covered = body.map((m) => m.id).slice(-500);
  const writeCoverage = async (reason) => {
    const saved = await memoryRequest('/summary', {
      key, period_start: periodStart, period_end: periodEnd, covered_ids: covered,
      text: reason, structured: '{}', model: 'coverage', value: 0, kind: 'coverage'
    }, 6000);
    log(`session summary: ${key} ${body.length} 条 -> 仅覆盖（${reason.slice(0, 12)}）`);
    return { ok: true, id: saved.id, messages: body.length, coverage: true };
  };

  // 便宜的信息量预检：整段都是“嗯/哈/？？”这种短闲聊时，不花 10k token 调模型。
  const allText = body.map((m) => String(m.text || '')).join('\n');
  const factish = /(记住|约定|答应|决定|计划|打算|明天|后天|下周|生日|喜欢|讨厌|不吃|过敏|地址|电话|叫什么|名字|几点|在哪|多少钱)/;
  const signalCount = body.filter((m) => {
    const t = String(m.text || '');
    return t.length >= 12 || /[?？]/.test(t) || factish.test(t);
  }).length;
  const lowSignalMin = Math.max(1, Number(cfg.socialV2?.context?.summaryLowSignalMin) || 3);
  if (!force && allText.length < 1500 && signalCount < lowSignalMin) {
    return writeCoverage('（这段主要是简短闲聊，没有值得留的事实或话头）');
  }

  // 摘要前先看这个聊天已有的长期记忆：少写重复，facts 只写新的。
  const memoryQuery = body.slice(-3).map((m) => String(m.text || '').slice(0, 80)).join('\n').slice(-600);
  const related = memoryQuery
    ? await memoryRequest('/search', { query: memoryQuery, scope: key, k: 5, min_score: 0.2 }, 4000)
      .then((r) => (Array.isArray(r.results) ? r.results : [])).catch(() => [])
    : [];
  const output = await runHeadlessPrompt(buildSummaryPrompt(body, { memories: related }), 120000);
  const parsed = parseSummaryOutput(output);
  if (!parsed.summary) return { ok: false, reason: 'bad-output' };
  // 模型可能还是把旧事实写回来；落库前按记忆原文再去一层重。
  parsed.facts = filterNovelFacts(parsed.facts, related);
  // 有事实 / 没接完的话 / 人物 / 够长的叙述，才算“有信息量”；否则只存不注入。
  const useful = (parsed.facts?.length || 0) > 0
    || (parsed.open_loops?.length || 0) > 0
    || (parsed.people?.length || 0) > 0
    || parsed.summary.length >= 120;
  const value = useful ? 1 : 0.4;
  const kind = useful ? 'summary' : 'low';
  // 手动重摘要会覆盖同一段：先删掉旧摘要里 period_end 落在本段之后的那条。
  if (force) {
    const existing = await memoryRequest('/summaries', { key, limit: 20 }, 4000)
      .then((r) => r.summaries || []).catch(() => []);
    const cutoff = Number(body[0]?.at) || 0;
    for (const old of existing) {
      if (Number(old.period_end) >= cutoff) {
        await memoryRequest('/summary/delete', { key, id: old.id }, 4000).catch(() => {});
      }
    }
  }
  const saved = await memoryRequest('/summary', {
    key,
    period_start: periodStart,
    period_end: periodEnd,
    covered_ids: covered,
    text: parsed.summary,
    structured: JSON.stringify(parsed),
    model: 'deepseek-flash',
    value,
    kind
  }, 6000);
  log(`session summary: ${key} ${body.length} 条 -> ${saved.id}（${kind}）`);
  return { ok: true, id: saved.id, messages: body.length, value, kind };
}

async function maybeRotateSession(key) {
  if (cfg.socialV2?.context?.autoRotate === false) return { ok: false, reason: 'disabled' };
  const limit = Math.max(8, Number(cfg.socialV2?.context?.rotateTurns) || 40);
  if ((Number(state.sessionTurns?.[key]) || 0) < limit) return { ok: false, reason: 'not-enough' };
  const q = promptQueues.get(key);
  if (q && (q.running || q.queue.length)) return { ok: false, reason: 'busy' };
  if (!state.sessions[key]) return { ok: false, reason: 'no-session' };
  const st = getSocialV2State(key);
  const lastAct = Math.max(Number(st.lastIncomingAt) || 0, Number(st.lastAiReplyAt) || 0, Number(st.lastActionAt) || 0);
  if (Date.now() - lastAct < 60000) return { ok: false, reason: 'active' };
  const backoffMs = Math.max(1, Number(cfg.socialV2?.context?.summaryRetryMinutes) || 30) * 60000;
  if (Date.now() - (Number(summaryFailures.get(key)) || 0) < backoffMs) return { ok: false, reason: 'backoff' };
  const summary = await summarizeSession(key);
  if (!summary.ok) {
    summaryFailures.set(key, Date.now());
    return { ok: false, reason: summary.reason || 'summary-failed' };
  }
  summaryFailures.delete(key);
  const old = state.sessions[key];
  retireSession(key);
  state.sessionStartedAt = state.sessionStartedAt || {};
  state.sessionStartedAt[key] = Date.now();
  state.sessionTurns = state.sessionTurns || {};
  state.sessionTurns[key] = 0;
  saveState();
  log(`context rotate: ${key} 摘要 ${summary.messages} 条，旧会话 ${old} 已退役`);
  return { ok: true, summaryId: summary.id, retired: old, coverage: summary.coverage === true, value: summary.value };
}

// 控制台手动补摘要：路由只负责转交，异常统一在这里收口。
async function handleContextSummarize(req, res, readBody, sendJson) {
  try {
    const body = await readBody();
    const key = String(body.key || '');
    if (!/^(private|group):\d+$/.test(key)) {
      sendJson({ ok: false, error: 'key 必须是 private:ID 或 group:ID' }, 400);
      return;
    }
    const result = await summarizeSession(key, { force: true });
    sendJson(result.ok ? { ok: true, ...result } : { ok: false, error: result.reason || '摘要失败' });
  } catch (error) {
    sendJson({ ok: false, error: String(error?.message || error) }, 500);
  }
}

