    && typeof buildSummaryBlock === 'function'
    && cfg.socialV2?.context?.enabled !== false && /^(private|group):\d+$/.test(key)) {
    const budgetChars = Math.max(500, Math.min(20000, Number(cfg.socialV2?.context?.messagesChars) || 6000));
    const summaryChars = Math.max(500, Math.min(8000, Number(cfg.socialV2?.context?.summaryChars) || 2000));
    const bundle = await fetchContextBundle({
      key,
      port: Number(cfg.socialV2?.memoryRecall?.port ?? 9881),
      budgetChars,
      beforeAt: sessionWindowStart(key),
      timeoutMs: Number(cfg.socialV2?.memoryRecall?.timeoutMs ?? 1200)
    }).catch(() => ({ messages: [], summaries: [] }));
    summaryBlock = buildSummaryBlock(bundle.summaries, { maxChars: summaryChars });
    sessionBlock = buildSessionBlock(bundle.messages, { maxChars: budgetChars });
    if (sessionBlock || summaryBlock) log(`session context injected: ${bundle.messages.length} 条原文，${bundle.summaries.length} 条摘要`);
  }
  if (human && !shouldRecallMemory(currentMessage)) return summaryBlock + sessionBlock + compose();
  if (cfg.socialV2?.memoryRecall?.enabled === false) return human ? summaryBlock + sessionBlock + compose() : summaryBlock + sessionBlock + promptText;
  try {
    const st = getSocialV2State(key);
    const query = dailyRecallQueries.get(key) || recallQuery(st.recentMessages || []) || '';
    if (!query) return human ? summaryBlock + sessionBlock + compose() : summaryBlock + sessionBlock + promptText;
    const priority = await memoryRequest('/priority', { scope: memoryScope(key), subject_id: subjectId }, 1200).catch(() => ({ results: [] }));
    const res = await fetch(`http://127.0.0.1:${cfg.socialV2?.memoryRecall?.port ?? 9881}/search`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ query, scope: memoryScope(key), min_score: 0.4, k: Number(cfg.socialV2?.memoryRecall?.topK ?? 3) }),
      signal: AbortSignal.timeout(Number(cfg.socialV2?.memoryRecall?.timeoutMs ?? 1200))
    });
    if (!res.ok) throw new Error(`memory HTTP ${res.status}`);
    const j = await res.json();
    if (human) return summaryBlock + sessionBlock + compose(priority.results, j.results);
    const unique = new Map();
    for (const r of [...(priority.results || []), ...(j.results || [])]) if (!unique.has(r.id)) unique.set(r.id, r);
    const rows = [...unique.values()].filter((r) => Number(r.score) >= 0.4);
    if (!rows.length) return summaryBlock + sessionBlock + promptText;
    log(`memory recall injected: ${rows.length} 条`);
    return summaryBlock + sessionBlock + recallBlock(rows) + promptText;
  } catch (error) {
    log(`memory recall unavailable: ${error?.message || error}`);
    return summaryBlock + sessionBlock + (human ? buildHumanContext({ key, subjectId, currentMessage, options: humanOptions }) : '') + promptText;
  }
}

